async (page) => {
  await page.goto('${BASE_URL}');
  await page.getByRole('status').filter({ hasText: 'Saved on this device' }).waitFor();
  await page.getByRole('button', { name: 'Set budget', exact: true }).click();
  await page.getByLabel('Budget for day 1', { exact: true }).fill('50.50');
  await page.getByRole('button', { name: 'Save budget', exact: true }).click();
  await page.getByRole('button', { name: 'Edit Coffee & pastéis', exact: true }).click();
  await page.getByLabel('Planned cost', { exact: true }).fill('10.25');
  await page.getByRole('button', { name: 'Save changes', exact: true }).click();
  await page.reload();
  const summary = page.getByRole('region', { name: 'Daily budget', exact: true });
  await summary.getByText('40.25 remaining', { exact: true }).waitFor();
  if (!(await summary.innerText()).includes('50.50 budget')) throw Error('Budget did not persist');
  if (!(await summary.innerText()).includes('Planned 10.25')) throw Error('Planned cost did not persist');
  await page.getByRole('button', { name: 'Next day', exact: true }).click();
  await summary.getByText('Planned 0.00 · No budget set', { exact: true }).waitFor();
  await page.getByRole('button', { name: 'Previous day', exact: true }).click();
  await summary.getByText('40.25 remaining', { exact: true }).waitFor();
  if (await page.evaluate(() => document.documentElement.scrollWidth > innerWidth)) throw Error('Horizontal overflow');
  const dismiss = page.getByRole('button', { name: 'Dismiss notification' });
  if (await dismiss.count()) await dismiss.click();
}

async (page, checks) => {
  const summary = page.getByRole('region', { name: 'Daily budget', exact: true });
  await summary.getByText('40.25 remaining', { exact: true }).waitFor();
  if (await page.evaluate(() => document.documentElement.scrollWidth > innerWidth)) throw Error('Mobile horizontal overflow');
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.getByRole('button', { name: 'Edit budget', exact: true }).click();
  await page.getByRole('dialog').waitFor();
  await page.keyboard.press('Escape');
  await page.waitForFunction(() => document.activeElement?.textContent?.includes('Edit budget'));
  const motion = await page.getByRole('button', { name: 'Edit budget', exact: true }).evaluate(el => {
    const style = getComputedStyle(el);
    return { duration: style.transitionDuration, transform: style.transform, scale: style.scale };
  });
  if (motion.duration !== '0s' || !checks.isIdentityTransform(motion.transform) || !['none', '1'].includes(motion.scale)) throw Error('Reduced-motion control is not at rest');
}

async (page) => {
  const key = 'roam.trips.v1';
  const good = await page.evaluate(key => localStorage.getItem(key), key);
  const summary = page.getByRole('region', { name: 'Daily budget', exact: true });
  await page.getByRole('button', { name: 'Edit budget', exact: true }).click();
  await page.getByLabel('Budget for day 1', { exact: true }).fill('-1');
  await page.getByRole('button', { name: 'Save budget', exact: true }).click();
  if (!(await page.getByRole('dialog').isVisible())) throw Error('Invalid budget accepted');
  await page.getByLabel('Budget for day 1', { exact: true }).fill('0');
  await page.getByRole('button', { name: 'Save budget', exact: true }).click();
  await summary.getByText('10.25 over budget', { exact: true }).waitFor();
  await page.getByRole('button', { name: 'Edit budget', exact: true }).click();
  await page.getByLabel('Budget for day 1', { exact: true }).fill('');
  await page.getByRole('button', { name: 'Save budget', exact: true }).click();
  await summary.getByText('Planned 10.25 · No budget set', { exact: true }).waitFor();
  const legacy = JSON.parse(good);
  delete legacy.trips[0].dailyBudgetsCents;
  legacy.trips[0].activities.forEach(a => delete a.plannedCostCents);
  const raw = JSON.stringify(legacy);
  await page.evaluate(({ key, raw }) => localStorage.setItem(key, raw), { key, raw });
  await page.reload();
  await summary.getByText('Planned 0.00 · No budget set', { exact: true }).waitFor();
  if (await page.evaluate(key => localStorage.getItem(key), key) !== raw) throw Error('Legacy storage was rewritten on load');
  legacy.trips[0].dailyBudgetsCents = { 0: -1 };
  const corrupt = JSON.stringify(legacy);
  await page.evaluate(({ key, corrupt }) => localStorage.setItem(key, corrupt), { key, corrupt });
  await page.reload();
  await page.getByRole('alert').filter({ hasText: 'existing data has not been changed' }).waitFor();
  await page.getByRole('button', { name: 'Set budget', exact: true }).click();
  await page.getByLabel('Budget for day 1', { exact: true }).fill('100');
  await page.getByRole('button', { name: 'Save budget', exact: true }).click();
  if (await page.evaluate(key => localStorage.getItem(key), key) !== corrupt) throw Error('Corrupt storage was overwritten');
}
